"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/segmented-control.css";
import { Toggle } from "@base-ui/react/toggle";
import { ToggleGroup } from "@base-ui/react/toggle-group";
import { useState, type ReactNode } from "react";
import { cn } from "../../lib/cn";

export type SegmentedControlOption = {
  value: string;
  label: ReactNode;
  accessibleLabel?: string;
  icon?: ReactNode;
  disabled?: boolean;
};

export type SegmentedControlProps = {
  options: readonly SegmentedControlOption[];
  label: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string | null) => void;
  allowEmpty?: boolean;
  disabled?: boolean;
  orientation?: "horizontal" | "vertical";
  size?: "small" | "medium";
  className?: string;
};

export function SegmentedControl({
  options,
  label,
  value,
  defaultValue,
  onValueChange,
  allowEmpty = false,
  disabled = false,
  orientation = "horizontal",
  size = "medium",
  className,
}: SegmentedControlProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? options.find((option) => !option.disabled)?.value ?? null);
  const selectedValue = value === undefined ? uncontrolledValue : value;
  const handleValueChange = (nextValues: string[]) => {
    const nextValue = nextValues[0] ?? null;
    if (!allowEmpty && nextValue === null) return;
    if (value === undefined) setUncontrolledValue(nextValue);
    onValueChange?.(nextValue);
  };

  return (
    <ToggleGroup
      className={cn("whatiuse-segmented-control", className)}
      data-size={size}
      aria-label={label}
      value={selectedValue ? [selectedValue] : []}
      onValueChange={handleValueChange}
      disabled={disabled}
      orientation={orientation}
    >
      {options.map((option) => (
        <Toggle key={option.value} className="whatiuse-segmented-control__item" value={option.value} disabled={option.disabled} aria-label={option.accessibleLabel}>
          {option.icon && <span aria-hidden="true">{option.icon}</span>}
          <span>{option.label}</span>
        </Toggle>
      ))}
    </ToggleGroup>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-segmented-control {
  display: inline-flex;
  width: fit-content;
  max-width: 100%;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border-radius: 8px;
  background: var(--whatiuse-bg-subtle);
}

.whatiuse-segmented-control[data-orientation="vertical"] { flex-direction: column; align-items: stretch; }

.whatiuse-segmented-control__item { display: inline-flex; min-width: 0; height: 28px; align-items: center; justify-content: center; gap: 6px; padding: 0 9px; border: 0; border-radius: 6px; background: transparent; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-label); white-space: nowrap; cursor: pointer; transition: color var(--whatiuse-hover-duration), background-color var(--whatiuse-hover-duration), box-shadow var(--whatiuse-hover-duration), transform var(--whatiuse-press-duration) var(--whatiuse-ease-out); }

.whatiuse-segmented-control[data-size="small"] .whatiuse-segmented-control__item { height: 24px; padding-inline: 7px; font-size: var(--whatiuse-type-metadata); }

.whatiuse-segmented-control__item > span { display: inline-flex; min-width: 0; align-items: center; }

.whatiuse-segmented-control__item svg { width: 13px; height: 13px; }

.whatiuse-segmented-control__item[data-pressed] { background: var(--whatiuse-bg-control); color: var(--whatiuse-fg-default); box-shadow: var(--whatiuse-shadow-control); font-weight: 560; }

.whatiuse-segmented-control__item:focus-visible { z-index: 1; outline: 2px solid var(--whatiuse-focus-control); outline-offset: 1px; }

.whatiuse-segmented-control__item:active { transform: scale(.97); }

.whatiuse-segmented-control__item[data-disabled] { color: var(--whatiuse-fg-disabled); cursor: not-allowed; }

@media (hover: hover) and (pointer: fine) {
.whatiuse-segmented-control__item:not([data-disabled]):not([data-pressed]):hover { background: var(--whatiuse-hover); color: var(--whatiuse-fg-default); }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-segmented-control__item:active { transform: none; }
}
}
